Here's an Express.js route to retrieve a single document from MongoDB. I'll show you two versions:

## Using Mongoose (most common)

```javascript
const express = require('express');
const router = express.Router();
const Item = require('../models/Item'); // your Mongoose model

// GET /items/:id
router.get('/items/:id', async (req, res) => {
  try {
    const item = await Item.findById(req.params.id);

    if (!item) {
      return res.status(404).json({ message: 'Item not found' });
    }

    res.status(200).json(item);
  } catch (error) {
    // Handle invalid ObjectId format or DB errors
    if (error.kind === 'ObjectId') {
      return res.status(400).json({ message: 'Invalid ID format' });
    }
    res.status(500).json({ message: 'Server error', error: error.message });
  }
});

module.exports = router;
```

## Using the native MongoDB driver

```javascript
const { ObjectId } = require('mongodb');

router.get('/items/:id', async (req, res) => {
  try {
    // Validate the ID first — otherwise ObjectId creation throws
    if (!ObjectId.isValid(req.params.id)) {
      return res.status(400).json({ message: 'Invalid ID format' });
    }

    const db = req.app.locals.db; // assuming you stored the db connection on app
    const item = await db.collection('items').findOne({ _id: new ObjectId(req.params.id) });

    if (!item) {
      return res.status(404).json({ message: 'Item not found' });
    }

    res.status(200).json(item);
  } catch (error) {
    res.status(500).json({ message: 'Server error', error: error.message });
  }
});
```

## Key points

- **`req.params.id`** pulls the `:id` value from the URL (e.g., `GET /items/65a1b2c3d4e5f6...`).
- **Validate the ObjectId** — MongoDB IDs must be 24-character hex strings. Querying with an invalid ID will throw an error, which is why the checks are there.
- **Return 404 vs 400** — distinguish between "bad ID format" and "ID is valid but nothing exists with it."
- If you're querying by a field other than `_id`, just change the query, e.g.:

```javascript
const item = await Item.findOne({ slug: req.params.slug });
```

