    console.error('Failed to fetch weather:', error);
  }
}

getWeather();
```

The response (`data`) will look something like this:

```json
{
  "location": {
    "name": "New York",
    "region": "New York",
    "country": "United States of America",
    "localtime": "2024-06-15 14:30"
  },
  "current": {
