# 返回字符串中字符代码的函数

以下是几种常见语言的实现：

## C# 版本

```csharp
using System;

class Program
{
    // 返回字符串中所有字符的代码（整数数组）
    static int[] GetCharCodes(string str)
    {
        int[] codes = new int[str.Length];
        for (int i = 0; i < str.Length; i++)
        {
            codes[i] = str[i]; // char 隐式转换为 int（Unicode 码点）
        }
        return codes;
    }

    static void Main()
    {
        string str = "Hello World!";
        int[] codes = GetCharCodes(str);

        foreach (int code in codes)
        {
            Console.Write(code + " ");
        }
    }
}
```

**输出：**
```
72 101 108 108 111 32 87 111 114 108 100 33
```

## C++ 版本

```cpp
#include <iostream>
#include <string>
#include <vector>

std::vector<int> getCharCodes(const std::string& str)
{
    std::vector<int> codes;
    for (char c : str)
    {
        codes.push_back(static_cast<int>(c));
    }
    return codes;
}

int main()
{
    std::string str = "Hello World!";
    std::vector<int> codes = getCharCodes(str);

    for (int code : codes)
    {
        std::cout << code << " ";
    }
    return 0;
}
```

## 说明

| 字符 | ASCII/Unicode 码 |
|------|------------------|
| H | 72 |
| e | 101 |
| l | 108 |
| o | 111 |
| （空格） | 32 |
| W | 87 |
| ! | 33 |

如果你想要按十六进制输出，或者其他语言（Python、Java 等）的版本，可以告诉我，我再帮你调整。

# 随机打乱数字列表程序

下面提供几种不同语言的实现方案：

## Python 版本

### 方法一：使用内置模块（推荐）

```python
import random

def generate_shuffled_list(n, start=1):
    """生成 1 到 n 的随机打乱列表"""
    numbers = list(range(start, start + n))
    random.shuffle(numbers)
    return numbers

# 示例
if __name__ == "__main__":
    n = int(input("请输入列表长度: "))
    result = generate_shuffled_list(n)
    print(f"随机打乱后的列表: {result}")
```

### 方法二：手动实现洗牌算法

```python
import random

def generate_shuffled_list(n):
    """使用 Fisher-Yates 洗牌算法"""
    numbers = list(range(1, n + 1))
    for i in range(len(numbers) - 1, 0, -1):
        # 随机选一个索引 j (0 <= j <= i)
        j = random.randint(0, i)
        # 交换 numbers[i] 和 numbers[j]
        numbers[i], numbers[j] = numbers[j], numbers[i]
    return numbers

print(generate_shuffled_list(10))
# 输出示例: [7, 2, 9, 1, 5, 10, 3, 8, 4, 6]
```

### 方法三：生成随机范围的数字

```python
import random

def generate_random_numbers(n, min_val=0, max_val=100):
    """生成 n 个随机数字（可能有重复）"""
    return [random.randint(min_val, max_val) for _ in range(n)]

def generate_unique_random_numbers(n, min_val=0, max_val=100):
    """生成 n 个不重复的随机数字"""
    return random.sample(range(min_val, max_val + 1), n)

print(generate_unique_random_numbers(5, 1, 50))
# 输出示例: [23, 7, 41, 15, 36]
```

## Java 版本

```java
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class ShuffleList {
    public static void main(String[] args) {
        int n = 10;
        List<Integer> numbers = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            numbers.add(i);
        }

        Collections.shuffle(numbers);

        System.out.println("随机打乱后的列表: " + numbers);
        // 输出示例: [3, 7, 1, 9, 5, 10, 2, 8, 4, 6]
    }
}
```

## JavaScript 版本

```javascript
function generateShuffledList(n) {
    const numbers = Array.from({ length: n }, (_, i) => i + 1);

    // Fisher-Yates 洗牌算法
    for (let i = numbers.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [numbers[i], numbers[j]] = [numbers[j], numbers[i]];
    }

    return numbers;
}

console.log(generateShuffledList(10));
// 输出示例: [4, 9, 1, 7, 3, 10, 2, 8, 5, 6]
```

## 关键说明

| 要点 | 说明 |
|------|------|
| **Fisher-Yates 算法** | 经典洗牌算法，保证每种排列出现的概率相等，时间复杂度 O(n) |
| **`random.shuffle()`** | Python 内置方法，同样基于 Fisher-Yates，原地修改列表 |
| **`random.sample()`** | 适合从更大范围中抽取不重复的随机数 |

如果你有特定需求（比如指定范围、不重复、固定的随机种子等），可以告诉我，我可以调整代码！

# C++ 反转数组元素

## 方法一：手动实现（双指针法）

```cpp
#include <iostream>
using namespace std;

// 反转数组函数
void reverseArray(int arr[], int size) {
    int start = 0;
    int end = size - 1;

    while (start < end) {
        // 交换首尾元素
        int temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;

        // 移动指针
        start++;
        end--;
    }
}

// 打印数组函数
void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;
}

int main() {
    int arr[] = {1, 2, 3, 4, 5};
    int size = sizeof(arr) / sizeof(arr[0]);

    cout << "原数组: ";
    printArray(arr, size);

    reverseArray(arr, size);

    cout << "反转后: ";
    printArray(arr, size);

    return 0;
}
```

**输出结果：**
```
原数组: 1 2 3 4 5 
反转后: 5 4 3 2 1 
```

## 方法二：使用 STL 的 `std::reverse`

```cpp
#include <iostream>
#include <algorithm>  // 包含 std::reverse
using namespace std;

int main() {
    int arr[] = {1, 2, 3, 4, 5};
    int size = sizeof(arr) / sizeof(arr[0]);

    cout << "原数组: ";
    for (int i = 0; i < size; i++) cout << arr[i] << " ";
    cout << endl;

    // 一行代码完成反转
    reverse(arr, arr + size);

    cout << "反转后: ";
    for (int i = 0; i < size; i++) cout << arr[i] << " ";
    cout << endl;

    return 0;
}
```

## 方法三：使用 `std::vector`（更现代的写法）

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    vector<int> vec = {1, 2, 3, 4, 5};

    cout << "原数组: ";
    for (int num : vec) cout << num << " ";
    cout << endl;

    reverse(vec.begin(), vec.end());

    cout << "反转后: ";
    for (int num : vec) cout << num << " ";
    cout << endl;

    return 0;
}
```

## 说明

| 方法 | 时间复杂度 | 空间复杂度 | 特点 |
|------|-----------|-----------|------|
| 双指针法 | O(n) | O(1) | 手动实现，适合学习算法原理 |
| `std::reverse` | O(n) | O(1) | 简洁，实际开发推荐 |
| `std::vector` | O(n) | O(1) | 类型安全，无需手动管理大小 |

**推荐**：学习阶段建议掌握方法一的双指针交换思想；实际项目中直接使用 `std::reverse` 即可，它更安全且经过充分测试。
